UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: trust boundaries and data flows are undocumented.', method='Build and verify a data-flow and trust-boundary model against code, configuration, network calls, tools, stores and human approval points. Use least-privileged test identities; mutate tool names, arguments, object IDs and response fields. Recheck authorization at execution time and verify restricted response data is removed.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-005 assessed system, version, environment and scope for Trust boundaries and data flows are undocumented","ARL-KB-005 control configuration or source location showing how reduce the likelihood and impact of trust boundaries and data flows are undocumented and make the remaining risk visible.","ARL-KB-005 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-005 policy, authorization, tool or audit events proving whether the tested trust boundaries and data flows are undocumented path executed","ARL-KB-005 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-005 passes only when “Trust boundaries and data flows are undocumented” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-005 fails when reviewers cannot see where untrusted input becomes model context, where identities change, or where outputs reach tools and external systems, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-005 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='f32807e12b3481d5373457709d14296537bee6e4618991928e7c6f256bcc886c', updated_at='2026-08-06' WHERE entry_id='ARL-KB-005';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of trust boundaries and data flows are undocumented and make the remaining risk visible.', recommended_remediation='Maintain a versioned architecture model showing actors, inputs, stores, models, agents, tools, networks, approvals and evidence paths.', default_owner='Security architect', priority='P1', implementation_principles_json='["ARL-KB-005: enforce the decision outside the model before any material side effect.","ARL-KB-005: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-005: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-005, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Security architect on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-005 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-005: “Trust boundaries and data flows are undocumented” is no longer reproducible against the exact remediated version.","ARL-KB-005: Authorised in-scope use completes successfully, remains within the documented asset scope for trust boundaries and data flows are undocumented, and produces no unintended side effect.","ARL-KB-005: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-005: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='49a1f487d8e1f13d667e296837f121b8fe166088db52324319433e077b8a916a', updated_at='2026-08-06' WHERE entry_id='ARL-KB-005';
