UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Prompts, memories, logs and tool arguments may contain personal, confidential, regulated or secret data without suitable handling rules.","customer_symptom":"A user or operator may observe prompts, memories, logs and tool arguments may contain personal, confidential, regulated or secret data without suitable handling rules; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in prompts, memories, logs and tool arguments may contain personal, confidential, regulated or secret data without suitable handling rules, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents processing non-public data"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between agents processing non-public data and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If prompts, memories, logs and tool arguments may contain personal, confidential, regulated or secret data without suitable handling rules, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-006 control or enforcement change","ARL-KB-006 model, prompt, tool, identity, data-source or provider change","ARL-KB-006 bypass, incident or new attack evidence","ARL-KB-006 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='c446f390316609e3353c47ac1e0fe61e997692c7af068e5e71524ab6391ef6c0', updated_at='2026-08-06' WHERE id='ARL-KB-006';
