UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Prompt, model, tool, policy or data-source changes can reach production without threat modelling, tests or approval.","customer_symptom":"A user or operator may observe prompt, model, tool, policy or data-source changes can reach production without threat modelling, tests or approval; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in prompt, model, tool, policy or data-source changes can reach production without threat modelling, tests or approval, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all production agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between all production agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If prompt, model, tool, policy or data-source changes can reach production without threat modelling, tests or approval, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-009 control or enforcement change","ARL-KB-009 model, prompt, tool, identity, data-source or provider change","ARL-KB-009 bypass, incident or new attack evidence","ARL-KB-009 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='5b45cb26e3106e8722b6e0c6373f6f71e0f27dcac4e0a0ca08d243fbf41768a5', updated_at='2026-08-06' WHERE id='ARL-KB-009';
UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: security-relevant changes bypass review.', method='Inspect version history and deployment records for review gates covering prompts, models, tools, permissions, policies, schemas and providers. Bind approval to the exact action, canonical parameters, target, value, actor, environment, expiry and nonce. Mutate each field and replay the token; every variant must be denied.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-009 assessed system, version, environment and scope for Security-relevant changes bypass review","ARL-KB-009 control configuration or source location showing how reduce the likelihood and impact of security-relevant changes bypass review and make the remaining risk visible.","ARL-KB-009 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-009 policy, authorization, tool or audit events proving whether the tested security-relevant changes bypass review path executed","ARL-KB-009 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-009 passes only when “Security-relevant changes bypass review” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-009 fails when prompt, model, tool, policy or data-source changes can reach production without threat modelling, tests or approval, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-009 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='00933553fa687b14267da09315e620c39df376a3d0652547800a801f01d5615d', updated_at='2026-08-06' WHERE entry_id='ARL-KB-009';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of security-relevant changes bypass review and make the remaining risk visible.', recommended_remediation='Use change classification, code review, signed artefacts, automated negative tests, staged rollout and rollback for all security-relevant changes.', default_owner='Engineering owner', priority='P1', implementation_principles_json='["ARL-KB-009: enforce the decision outside the model before any material side effect.","ARL-KB-009: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-009: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-009, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Engineering owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-009 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-009: “Security-relevant changes bypass review” is no longer reproducible against the exact remediated version.","ARL-KB-009: Authorised in-scope use completes successfully, remains within the documented asset scope for security-relevant changes bypass review, and produces no unintended side effect.","ARL-KB-009: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-009: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='b9b1b7b9946e72476dfabc64e509a1d0e43801aa319ab93c21a6e6e21511d091', updated_at='2026-08-06' WHERE entry_id='ARL-KB-009';
