 required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-015 control or enforcement change","ARL-KB-015 model, prompt, tool, identity, data-source or provider change","ARL-KB-015 bypass, incident or new attack evidence","ARL-KB-015 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='7dc73b5a99c2d312d211c565c9073f609297890a7965499cd0e507ba28f8753d', updated_at='2026-08-06' WHERE id='ARL-KB-015';
