UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: session tokens are weak or mishandled.', method='Test token entropy, cookie attributes, rotation, logout, expiry, concurrent sessions, log leakage and fixation. Execute the documented check for “Session tokens are weak or mishandled” against the exact assessed version, then vary identity, scope, malformed input, replay and a bypass path relevant to the control.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-021 assessed system, version, environment and scope for Session tokens are weak or mishandled","ARL-KB-021 control configuration or source location showing how reduce the likelihood and impact of session tokens are weak or mishandled and make the remaining risk visible.","ARL-KB-021 positive and abuse inputs with expected and observed outputs for agent and model context","ARL-KB-021 policy, authorization, tool or audit events proving whether the tested session tokens are weak or mishandled path executed","ARL-KB-021 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-021 passes only when “Session tokens are weak or mishandled” is not reproducible through the documented abuse cases, the valid workflow remains bounded to agent and model context, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-021 fails when predictable, long-lived, logged or broadly scoped sessions can be stolen or reused, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-021 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='cf6ff378ad82030e4ec413bd7cf5ea8eb875ab5aa449dc8b39b84a524722f4b7', updated_at='2026-08-06' WHERE entry_id='ARL-KB-021';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of session tokens are weak or mishandled and make the remaining risk visible.', recommended_remediation='Use strong opaque tokens, secure cookies, server-side revocation, rotation after privilege change and bounded idle/absolute lifetimes.', default_owner='Application security owner', priority='P1', implementation_principles_json='["ARL-KB-021: enforce the decision outside the model before any material side effect.","ARL-KB-021: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-021: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-021, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-021 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-021: “Session tokens are weak or mishandled” is no longer reproducible against the exact remediated version.","ARL-KB-021: Authorised in-scope use completes successfully, remains within the documented asset scope for session tokens are weak or mishandled, and produces no unintended side effect.","ARL-KB-021: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-021: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='d3ab547d4fceb67d0991840d7c02eed1546178f6e98eda3e3bfe0e69de28cec4', updated_at='2026-08-06' WHERE entry_id='ARL-KB-021';
