UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Internal components trust network location or a shared secret, so compromise of one service grants broad access.","customer_symptom":"A user or operator may observe internal components trust network location or a shared secret, so compromise of one service grants broad access; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in internal components trust network location or a shared secret, so compromise of one service grants broad access, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["distributed agents"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between distributed agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If internal components trust network location or a shared secret, so compromise of one service grants broad access, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-026 control or enforcement change","ARL-KB-026 model, prompt, tool, identity, data-source or provider change","ARL-KB-026 bypass, incident or new attack evidence","ARL-KB-026 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='52ab65f2df31375c1a7d5ff96aa86cce3a427b9b5a1c536a02c9f3c3da26d074', updated_at='2026-08-06' WHERE id='ARL-KB-026';
UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: service-to-service identity is unauthenticated or shared.', method='Inspect calls between orchestrator, model gateway, tool gateway, vector store and evidence service for mutual identity and audience checks. Execute the documented check for “Service-to-service identity is unauthenticated or shared” against the exact assessed version, then vary identity, scope, malformed input, replay and a bypass path relevant to the control.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-026 assessed system, version, environment and scope for Service-to-service identity is unauthenticated or shared","ARL-KB-026 control configuration or source location showing how reduce the likelihood and impact of service-to-service identity is unauthenticated or shared and make the remaining risk visible.","ARL-KB-026 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-026 policy, authorization, tool or audit events proving whether the tested service-to-service identity is unauthenticated or shared path executed","ARL-KB-026 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-026 passes only when “Service-to-service identity is unauthenticated or shared” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-026 fails when internal components trust network location or a shared secret, so compromise of one service grants broad access, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-026 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='603393161d0a079910d53d15c064d237b93ca9e5ee322a5ce37d74092397142a', updated_at='2026-08-06' WHERE entry_id='ARL-KB-026';
