ange_triggers":["ARL-KB-027 control or enforcement change","ARL-KB-027 model, prompt, tool, identity, data-source or provider change","ARL-KB-027 bypass, incident or new attack evidence","ARL-KB-027 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='8235a07a5f0d75afab4c9b812d94558b93dec60e249f6f4540c87d0a10bee49a', updated_at='2026-08-06' WHERE id='ARL-KB-027';
