tions='This bounded ARL-KB-027 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='8920039848637b68388563cfceca08fb57ec8be081f571b6165bb0f115c6e35f', updated_at='2026-08-06' WHERE entry_id='ARL-KB-027';
