e.', limitations='This bounded ARL-KB-028 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='d0b6cf207a5a3582670b7793b5809c8324beebc478d25b7d78dbbde4aaa311c5', updated_at='2026-08-06' WHERE entry_id='ARL-KB-028';
