UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Multiple people or services act under one identity, making approvals and evidence non-attributable.","customer_symptom":"A user or operator may observe multiple people or services act under one identity, making approvals and evidence non-attributable; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in multiple people or services act under one identity, making approvals and evidence non-attributable, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["organisations requiring accountable decisions"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between organisations requiring accountable decisions and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If multiple people or services act under one identity, making approvals and evidence non-attributable, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-029 control or enforcement change","ARL-KB-029 model, prompt, tool, identity, data-source or provider change","ARL-KB-029 bypass, incident or new attack evidence","ARL-KB-029 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='227019fab1945e2a7ea9cc46812bb9819a89ccda92bb2df747a0e95fb00320b9', updated_at='2026-08-06' WHERE id='ARL-KB-029';
UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: shared accounts destroy accountability.', method='Inspect identity records, audit trails and access patterns for shared credentials or generic approver names. Bind approval to the exact action, canonical parameters, target, value, actor, environment, expiry and nonce. Mutate each field and replay the token; every variant must be denied.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-029 assessed system, version, environment and scope for Shared accounts destroy accountability","ARL-KB-029 control configuration or source location showing how reduce the likelihood and impact of shared accounts destroy accountability and make the remaining risk visible.","ARL-KB-029 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-029 policy, authorization, tool or audit events proving whether the tested shared accounts destroy accountability path executed","ARL-KB-029 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-029 passes only when “Shared accounts destroy accountability” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-029 fails when multiple people or services act under one identity, making approvals and evidence non-attributable, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-029 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='4ae894fdcfacd112b77e48f0af15b4c16ae166fe925a6051febfcc52f23640eb', updated_at='2026-08-06' WHERE entry_id='ARL-KB-029';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of shared accounts destroy accountability and make the remaining risk visible.', recommended_remediation='Provide individual and workload identities, prohibit shared privileged accounts and bind audit records to verified principals.', default_owner='Identity owner', priority='P1', implementation_principles_json='["ARL-KB-029: enforce the decision outside the model before any material side effect.","ARL-KB-029: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-029: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-029, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Identity owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-029 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-029: “Shared accounts destroy accountability” is no longer reproducible against the exact remediated version.","ARL-KB-029: Authorised in-scope use completes successfully, remains within the documented asset scope for shared accounts destroy accountability, and produces no unintended side effect.","ARL-KB-029: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-029: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='0a398744bc3d055fe6062dc183061cf10a1b05efb58c9e369a834f37666a0fa7', updated_at='2026-08-06' WHERE entry_id='ARL-KB-029';
