UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: encoding and canonicalisation bypass controls.', method='Apply equivalent malicious inputs using mixed encodings, confusables, nested serialization, whitespace and case changes. Exercise loopback, private, link-local, multicast and reserved ranges; cloud metadata endpoints; redirects; DNS rebinding; IPv4/IPv6 and alternate numeric IP forms. Resolve and validate every hop and require fail-closed denial.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-037 assessed system, version, environment and scope for Encoding and canonicalisation bypass controls","ARL-KB-037 control configuration or source location showing how reduce the likelihood and impact of encoding and canonicalisation bypass controls and make the remaining risk visible.","ARL-KB-037 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-037 policy, authorization, tool or audit events proving whether the tested encoding and canonicalisation bypass controls path executed","ARL-KB-037 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-037 passes only when “Encoding and canonicalisation bypass controls” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tool endpoints and downstream systems and financial, administrative or state-changing actions, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-037 fails when different unicode, url, json, html or base64 forms let the same dangerous instruction evade filters, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-037 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='1175c3e56598385f9a3812b2b20807d8cef43889ad7c2f3f361b86c0ebf152ac', updated_at='2026-08-06' WHERE entry_id='ARL-KB-037';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of encoding and canonicalisation bypass controls and make the remaining risk visible.', recommended_remediation='Canonicalise once at the boundary, validate structured fields after decoding, avoid blacklist-only filtering and test equivalence classes.', default_owner='Application security owner', priority='P1', implementation_principles_json='["ARL-KB-037: enforce the decision outside the model before any material side effect.","ARL-KB-037: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-037: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-037, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-037 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-037: “Encoding and canonicalisation bypass controls” is no longer reproducible against the exact remediated version.","ARL-KB-037: Authorised in-scope use completes successfully, remains within the documented asset scope for encoding and canonicalisation bypass controls, and produces no unintended side effect.","ARL-KB-037: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-037: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='e08571ed8c7bd22f8b3de79592ed540d39358bde37e964694a5ced1b5e812c12', updated_at='2026-08-06' WHERE entry_id='ARL-KB-037';
