ue":"2026-11-03","change_triggers":["ARL-KB-038 control or enforcement change","ARL-KB-038 model, prompt, tool, identity, data-source or provider change","ARL-KB-038 bypass, incident or new attack evidence","ARL-KB-038 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='708a3bcb030e5e3f0e4f777daac03371c65ba834b25d1657eb5aeef34d1d2a73', updated_at='2026-08-06' WHERE id='ARL-KB-038';
