UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Prompts include secrets, full records or personal data that are not needed for the task.","customer_symptom":"A user or operator may observe prompts include secrets, full records or personal data that are not needed for the task; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in prompts include secrets, full records or personal data that are not needed for the task, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","model and dependency artefacts","build, registry and deployment provenance","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents handling non-public data"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between agents handling non-public data and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If prompts include secrets, full records or personal data that are not needed for the task, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-10-04","change_triggers":["ARL-KB-041 control or enforcement change","ARL-KB-041 model, prompt, tool, identity, data-source or provider change","ARL-KB-041 bypass, incident or new attack evidence","ARL-KB-041 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='1cb1c947535cc5075bad49842ac04bebb00fad125002efbad0ea00afa49524db', updated_at='2026-08-06' WHERE id='ARL-KB-041';
UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: sensitive data is sent to the model unnecessarily.', method='Trace representative requests from source to provider and compare every field with the minimum data required for the stated purpose. Execute the documented check for “Sensitive data is sent to the model unnecessarily” against the exact assessed version, then vary identity, scope, malformed input, replay and a bypass path relevant to the control.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-041 assessed system, version, environment and scope for Sensitive data is sent to the model unnecessarily","ARL-KB-041 control configuration or source location showing how reduce the likelihood and impact of sensitive data is sent to the model unnecessarily and make the remaining risk visible.","ARL-KB-041 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-041 policy, authorization, tool or audit events proving whether the tested sensitive data is sent to the model unnecessarily path executed","ARL-KB-041 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-041 passes only when “Sensitive data is sent to the model unnecessarily” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-041 fails when prompts include secrets, full records or personal data that are not needed for the task, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-041 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='b37fab6412a6ed7ad3b41ca260f769968c87aaa97a046b78d5cf8926b121784e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-041';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of sensitive data is sent to the model unnecessarily and make the remaining risk visible.', recommended_remediation='Minimise and pseudonymise inputs, redact secrets, use field allowlists and choose provider settings that meet retention and training constraints.', default_owner='Data protection owner', priority='P0', implementation_principles_json='["ARL-KB-041: enforce the decision outside the model before any material side effect.","ARL-KB-041: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-041: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-041, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Data protection owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-041 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-041: “Sensitive data is sent to the model unnecessarily” is no longer reproducible against the exact remediated version.","ARL-KB-041: Authorised in-scope use completes successfully, remains within the documented asset scope for sensitive data is sent to the model unnecessarily, and produces no unintended side effect.","ARL-KB-041: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-041: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='6dff767a25161d1951c3fc8b0511f173f005d4d60837160c0fa7018351ba62b9', updated_at='2026-08-06' WHERE entry_id='ARL-KB-041';
