UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The agent stores whole conversations, attachments or tool results indefinitely because they may be useful later.","customer_symptom":"A user or operator may observe the agent stores whole conversations, attachments or tool results indefinitely because they may be useful later; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in the agent stores whole conversations, attachments or tool results indefinitely because they may be useful later, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents processing personal data"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between agents processing personal data and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the agent stores whole conversations, attachments or tool results indefinitely because they may be useful later, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-042 control or enforcement change","ARL-KB-042 model, prompt, tool, identity, data-source or provider change","ARL-KB-042 bypass, incident or new attack evidence","ARL-KB-042 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='6e82fa2adbd06f5a91139937b99c30ba8f95028326dfc97b76b87398c421b8d1', updated_at='2026-08-06' WHERE id='ARL-KB-042';
