ce.', limitations='This bounded ARL-KB-042 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='0e0d1b53357df9bb8bdf1cca702d8fc108e42ae478d43232f2eac2bd577f999e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-042';
