UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Weak access control, shared indexes or unrestricted similarity queries leak sensitive records or membership.","customer_symptom":"A user or operator may observe weak access control, shared indexes or unrestricted similarity queries leak sensitive records or membership; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in weak access control, shared indexes or unrestricted similarity queries leak sensitive records or membership, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["embedding and vector systems"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between embedding and vector systems and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If weak access control, shared indexes or unrestricted similarity queries leak sensitive records or membership, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-045 control or enforcement change","ARL-KB-045 model, prompt, tool, identity, data-source or provider change","ARL-KB-045 bypass, incident or new attack evidence","ARL-KB-045 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='9185cf54113691be34924282188647637d56710f7351e220ad2030c14afabe50', updated_at='2026-08-06' WHERE id='ARL-KB-045';
UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: vector and embedding services expose raw or inferable data.', method='Test direct vector API access, namespace isolation, metadata filters, enumeration, export and inference across identities. Execute the documented check for “Vector and embedding services expose raw or inferable data” against the exact assessed version, then vary identity, scope, malformed input, replay and a bypass path relevant to the control.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-045 assessed system, version, environment and scope for Vector and embedding services expose raw or inferable data","ARL-KB-045 control configuration or source location showing how reduce the likelihood and impact of vector and embedding services expose raw or inferable data and make the remaining risk visible.","ARL-KB-045 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-045 policy, authorization, tool or audit events proving whether the tested vector and embedding services expose raw or inferable data path executed","ARL-KB-045 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-045 passes only when “Vector and embedding services expose raw or inferable data” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-045 fails when weak access control, shared indexes or unrestricted similarity queries leak sensitive records or membership, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-045 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='3dcdbb63853745f6d536d22688b9443889bf95ccf2a0d14bdd6de3bac024ab40', updated_at='2026-08-06' WHERE entry_id='ARL-KB-045';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of vector and embedding services expose raw or inferable data and make the remaining risk visible.', recommended_remediation='Private-network and identity-protect vector services, minimise metadata, isolate indexes, rate limit queries and monitor bulk or probing behaviour.', default_owner='Data platform owner', priority='P1', implementation_principles_json='["ARL-KB-045: enforce the decision outside the model before any material side effect.","ARL-KB-045: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-045: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-045, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Data platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-045 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-045: “Vector and embedding services expose raw or inferable data” is no longer reproducible against the exact remediated version.","ARL-KB-045: Authorised in-scope use completes successfully, remains within the documented asset scope for vector and embedding services expose raw or inferable data, and produces no unintended side effect.","ARL-KB-045: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-045: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='f1bd567b63a12c5cb830fb4d2e7275bddb8fb1114889ed3e7d33d973cc8d8dd2', updated_at='2026-08-06' WHERE entry_id='ARL-KB-045';
