UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"An attacker asks the agent to summarise, encode or send information that the model can access but the user cannot.","customer_symptom":"A user or operator may observe an attacker asks the agent to summarise, encode or send information that the model can access but the user cannot; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in an attacker asks the agent to summarise, encode or send information that the model can access but the user cannot, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents with confidential context"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between agents with confidential context and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If an attacker asks the agent to summarise, encode or send information that the model can access but the user cannot, accountable operators may need to stop affected actions, investi