UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A token issued before user revocation, role downgrade, policy update or incident remains executable.","customer_symptom":"A user or operator may observe a token issued before user revocation, role downgrade, policy update or incident remains executable; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in a token issued before user revocation, role downgrade, policy update or incident remains executable, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","backups, runtime state and recovery infrastructure","service availability and data integrity","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents requiring human approval"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between agents requiring human approval and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a token issued before user revocation, role downgrade, policy update or incident remains executable, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-10-04","change_triggers":["ARL-KB-070 control or enforcement change","ARL-KB-070 model, prompt, tool, identity, data-source or provider change","ARL-KB-070 bypass, incident or new attack evidence","ARL-KB-070 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='acf407782cffc9f083b831f69b31ed9561bce3e384780744fc93d55c3e9b04c3', updated_at='2026-08-06' WHERE id='ARL-KB-070';
