UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: model provenance cannot be verified.', method='Verify source, licence, digest or immutable provider revision, signing evidence and transfer path for the deployed model. Verify model provenance, signed dependency and container digests, MCP-server trust, allowed registries and rejection of executable or unsafe model formats before loading.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-073 assessed system, version, environment and scope for Model provenance cannot be verified","ARL-KB-073 control configuration or source location showing how reduce the likelihood and impact of model provenance cannot be verified and make the remaining risk visible.","ARL-KB-073 positive and abuse inputs with expected and observed outputs for model and dependency artefacts and build, registry and deployment provenance","ARL-KB-073 policy, authorization, tool or audit events proving whether the tested model provenance cannot be verified path executed","ARL-KB-073 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-073 passes only when “Model provenance cannot be verified” is not reproducible through the documented abuse cases, the valid workflow remains bounded to model and dependency artefacts and build, registry and deployment provenance, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-073 fails when weights or endpoints may be substituted, tampered with or obtained from an untrusted publisher, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-073 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='3bec90c6a4bb4eda0d153cb6ea7da81ada6e57e5db748d6acb0f15e9a84fe82e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-073';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of model provenance cannot be verified and make the remaining risk visible.', recommended_remediation='Use approved publishers, immutable manifests, digest verification, quarantined intake and provenance records tied to deployment.', default_owner='ML supply-chain owner', priority='P0', implementation_principles_json='["ARL-KB-073: enforce the decision outside the model before any material side effect.","ARL-KB-073: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-073: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-073, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the ML supply-chain owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-073 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-073: “Model provenance cannot be verified” is no longer reproducible against the exact remediated version.","ARL-KB-073: Authorised in-scope use completes successfully, remains within the documented asset scope for model provenance cannot be verified, and produces no unintended side effect.","ARL-KB-073: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-073: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='dcc217064f28ea0f992438b34eba2904cd79acff166452710c77e4d12f8ed250', updated_at='2026-08-06' WHERE entry_id='ARL-KB-073';
