UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of model output is trusted as safe code or data and make the remaining risk visible.', recommended_remediation='Treat output as untrusted, use typed schemas, contextual encoding, parameterised APIs and independent policy validation.', default_owner='Application security owner', priority='P0', implementation_principles_json='["ARL-KB-081: enforce the decision outside the model before any material side effect.","ARL-KB-081: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-081: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-081, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-081 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-081: “Model output is trusted as safe code or data” is no longer reproducible against the exact remediated version.","ARL-KB-081: Authorised in-scope use completes successfully, remains within the documented asset scope for model output is trusted as safe code or data, and produces no unintended side effect.","ARL-KB-081: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-081: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='40784c83d92b7d42716364dcf47c727455b1aa5d43f75bd2bef9e08452cccae6', updated_at='2026-08-06' WHERE entry_id='ARL-KB-081';
