UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Agent output rendered as HTML or Markdown executes script or unsafe links in a user''s browser.","customer_symptom":"A user or operator may observe agent output rendered as html or markdown executes script or unsafe links in a user''s browser; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in agent output rendered as html or markdown executes script or unsafe links in a user''s browser, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["web-displayed agent output"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between web-displayed agent output and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If agent output rendered as html or markdown executes script or unsafe links in a user''s browser, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-10-04","change_triggers":["ARL-KB-082 control or enforcement change","ARL-KB-082 model, prompt, tool, identity, data-source or provider change","ARL-KB-082 bypass, incident or new attack evidence","ARL-KB-082 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='9cf2d8feb77799a339ebfce7b5b426c38f2375ae2b9e593254a9b6f79927a83e', updated_at='2026-08-06' WHERE id='ARL-KB-082';
