r risks outside the stated identities, inputs, environment and version.', content_digest='c6ad468971f6525aa424928a6d8e82e4f7e6de9e3c3682a1c5721a64f3766516', updated_at='2026-08-06' WHERE entry_id='ARL-KB-082';
