UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of logs and traces contain secrets or personal data and make the remaining risk visible.', recommended_remediation='Redact at source, use structured allowlists, separate security evidence from raw content, limit access and apply retention.', default_owner='Observability and privacy owner', priority='P1', implementation_principles_json='["ARL-KB-089: enforce the decision outside the model before any material side effect.","ARL-KB-089: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-089: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-089, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Observability and privacy owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-089 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-089: “Logs and traces contain secrets or personal data” is no longer reproducible against the exact remediated version.","ARL-KB-089: Authorised in-scope use completes successfully, remains within the documented asset scope for logs and traces contain secrets or personal data, and produces no unintended side effect.","ARL-KB-089: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-089: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='eb8c8796d3cd1654e6cc2ef58e2b99f57cd045823a1a8f1f91edc43a2022cae4', updated_at='2026-08-06' WHERE entry_id='ARL-KB-089';
