UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Prompts, policies, vector indexes, approvals, remediation and audit records cannot be restored consistently.","customer_symptom":"A user or operator may observe prompts, policies, vector indexes, approvals, remediation and audit records cannot be restored consistently; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in prompts, policies, vector indexes, approvals, remediation and audit records cannot be restored consistently, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","backups, runtime state and recovery infrastructure","service availability and data integrity","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["stateful hosted platforms"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between stateful hosted platforms and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If prompts, policies, vector indexes, approvals, remediation and audit records cannot be restored consistently, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold de