UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: fixes are accepted without adversarial retest.', method='Repeat the original negative test plus bypass, regression, concurrency and authorization cases against the exact remediated version. Execute the documented check for “Fixes are accepted without adversarial retest” against the exact assessed version, then vary identity, scope, malformed input, replay and a bypass path relevant to the control.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-106 assessed system, version, environment and scope for Fixes are accepted without adversarial retest","ARL-KB-106 control configuration or source location showing how reduce the likelihood and impact of fixes are accepted without adversarial retest and make the remaining risk visible.","ARL-KB-106 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-106 policy, authorization, tool or audit events proving whether the tested fixes are accepted without adversarial retest path executed","ARL-KB-106 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-106 passes only when “Fixes are accepted without adversarial retest” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tool endpoints and downstream systems and financial, administrative or state-changing actions, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-106 fails when a code change or declaration closes the finding even though the original attack still succeeds through another path, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-106 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='50f468fbc959ef2032eb45ca7528afdec2feb816b96b449d8fb956fbb2480bea', updated_at='2026-08-06' WHERE entry_id='ARL-KB-106';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of fixes are accepted without adversarial retest and make the remaining risk visible.', recommended_remediation='Define retest acceptance before remediation, preserve original evidence, execute independent tests and record open limitations.', default_owner='Independent retest owner', priority='P0', implementation_principles_json='["ARL-KB-106: enforce the decision outside the model before any material side effect.","ARL-KB-106: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-106: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-106, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Independent retest owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-106 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-106: “Fixes are accepted without adversarial retest” is no longer reproducible against the exact remediated version.","ARL-KB-106: Authorised in-scope use completes successfully, remains within the documented asset scope for fixes are accepted without adversarial retest, and produces no unintended side effect.","ARL-KB-106: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-106: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='1d7cfaea822f38c9115e5f0dd06b6d84f9c4a653595ff9c21e5b56ef0009f91d', updated_at='2026-08-06'